using System.IO;
using NeoCompose.Export;
using Newtonsoft.Json;
using NUnit.Framework;

namespace NeoCompose.Tests
{
    /// <summary>
    /// Newtonsoft.Json round-trip coverage for <see cref="ProjectExport"/>
    /// and the full IR tree rooted on <see cref="Attribute.getter"/>.
    ///
    /// Two fixtures back the suite:
    ///
    ///  - <c>synth-example.json</c> — generated by the TS-side dump
    ///    script (`scripts/dump-synth-export.ts`). Designed to exercise
    ///    every IR variant: list / dict literals, force-unwrap,
    ///    isCheck, callGetter, coalesce, where / count functions, both
    ///    arithmetic + boolean operations, and the four instruction
    ///    kinds (variable / if / return / throw, plus the bare
    ///    <c>return;</c> null-pointer case).
    ///  - <c>project-example.json</c> — a real-world export captured
    ///    from a live Neo-Compose authoring session.
    ///
    /// Tests load each fixture from
    /// <c>Packages/com.ryanbliss.neocompose/Tests/</c> (the canonical
    /// Unity Package Manager path for local-path references and
    /// registry installs alike) and pass the JSON through
    /// <see cref="JsonConvert.DeserializeObject{T}(string)"/>.
    /// </summary>
    public class ProjectExportRoundTripTests
    {
        private const string PackageRoot =
            "Packages/com.ryanbliss.neocompose/Tests";

        private static string LoadFixture(string fileName)
        {
            return File.ReadAllText(Path.Combine(PackageRoot, fileName));
        }

        private static ProjectExport Deserialize(string json)
        {
            return JsonConvert.DeserializeObject<ProjectExport>(json);
        }

        // --------------------------------------------------------------
        // Synthesized fixture — exercises every IR variant.
        // --------------------------------------------------------------

        [Test]
        public void SynthFixture_DeserializesIntoProjectExport()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));

            Assert.IsNotNull(export);
            Assert.IsNotNull(export.project);
            Assert.IsNotNull(export.attributes);
            Assert.IsNotNull(export.values);
            Assert.IsNotNull(export.types);
            Assert.IsNotNull(export.enums);
            Assert.Greater(export.attributes.Count, 0);
        }

        [Test]
        public void SynthFixture_ProjectFields_RoundTrip()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            Assert.AreEqual("Test Project", export.project.name);
            Assert.IsNotEmpty(export.project.id);
            Assert.IsNotEmpty(export.project.rootAssetsAttributeId);
            Assert.IsNotEmpty(export.project.rootSaveFileAttributeId);
        }

        [Test]
        public void SynthFixture_StringAttribute_DefaultValueIsString()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            var name = export.attributes["attr-name"];
            Assert.AreEqual(AttributeType.String, name.type);
            // Polymorphic value rides as JToken — extract via Value<T>.
            Assert.AreEqual("Hero", name.defaultValue.value.ToObject<string>());
        }

        [Test]
        public void SynthFixture_IntAttribute_DefaultValueIsInt()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            var health = export.attributes["attr-health"];
            Assert.AreEqual(AttributeType.Int, health.type);
            Assert.AreEqual(100, health.defaultValue.value.ToObject<int>());
        }

        [Test]
        public void SynthFixture_FloatAttribute_DefaultValueIsFloat()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            var speed = export.attributes["attr-speed"];
            Assert.AreEqual(AttributeType.Float, speed.type);
            Assert.AreEqual(7.5f, speed.defaultValue.value.ToObject<float>(), 0.0001f);
        }

        [Test]
        public void SynthFixture_BoolAttribute_DefaultValueIsBool()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            var alive = export.attributes["attr-isalive"];
            Assert.AreEqual(AttributeType.Bool, alive.type);
            Assert.IsTrue(alive.defaultValue.value.ToObject<bool>());
        }

        [Test]
        public void SynthFixture_DictionaryAttribute_DefaultValueIsRecord()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            var inv = export.attributes["attr-inventory"];
            Assert.AreEqual(AttributeType.Dictionary, inv.type);
            // Custom / Dictionary attribute values are JSON objects keyed
            // by schema-key → valueId. Extract via JToken.ToObject.
            var dict = inv.defaultValue.value
                .ToObject<System.Collections.Generic.Dictionary<string, string>>();
            Assert.AreEqual("v-sword", dict["sword"]);
            Assert.AreEqual("v-shield", dict["shield"]);
        }

        [Test]
        public void SynthFixture_ListAttribute_DefaultValueIsStringArray()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            var tags = export.attributes["attr-tags"];
            Assert.AreEqual(AttributeType.List, tags.type);
            var list = tags.defaultValue.value.ToObject<string[]>();
            CollectionAssert.AreEqual(new[] { "v-a", "v-b" }, list);
        }

        [Test]
        public void SynthFixture_NSGetterReturnTypeInfo_IsCollectionTypeInfo()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            var score = export.attributes["attr-score"];
            Assert.AreEqual(AttributeType.NSGetter, score.type);
            // The synth fixture's Score returns Int, so returnTypeInfo is
            // PrimitiveTypeInfo. Custom subtype assertion via `is`.
            Assert.IsInstanceOf<PrimitiveTypeInfo>(score.returnTypeInfo);
            Assert.AreEqual(AttributeType.Int, score.returnTypeInfo.type);
            Assert.IsTrue(score.returnTypeInfo.required);
        }

        [Test]
        public void SynthFixture_NSGetterCompiledIR_DispatchesAllInstructionKinds()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            var score = export.attributes["attr-score"];
            var getter = score.getter;
            Assert.IsNotNull(getter);
            Assert.IsNotEmpty(getter.instructions);

            // The synth fixture's getter walks: variable, variable, if
            // (with nested arithmetic + isCheck + force-unwrap +
            // coalesce + keyOf + listLiteral + where + count), and a
            // bare `return null;`.
            Assert.IsInstanceOf<VariableInstruction>(getter.instructions[0]);
            Assert.IsInstanceOf<VariableInstruction>(getter.instructions[1]);
            Assert.IsInstanceOf<IfInstruction>(getter.instructions[2]);
            Assert.IsInstanceOf<ReturnInstruction>(getter.instructions[3]);

            // The if-instruction's `else` field is renamed to
            // `elseInstructions` on the C# side via [JsonProperty].
            var ifInstr = (IfInstruction)getter.instructions[2];
            Assert.IsNotEmpty(ifInstr.branches);
            Assert.IsNotEmpty(ifInstr.elseInstructions);
            Assert.IsInstanceOf<ThrowInstruction>(ifInstr.elseInstructions[0]);

            // Bare `return;` → wire `pointer: null` → C# null.
            var returnInstr = (ReturnInstruction)getter.instructions[3];
            Assert.IsNull(returnInstr.pointer);
        }

        [Test]
        public void SynthFixture_NSGetterIR_PreservesArithmeticOperationPointer()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            var score = export.attributes["attr-score"];

            // First instruction: `local int x = 1 + 2;`
            var firstVar = ((VariableInstruction)score.getter.instructions[0]).variable;
            var opPointer = (OperationPointer)firstVar.pointer;
            var arithOp = (ArithmeticOperation)opPointer.operation;
            Assert.AreEqual(ArithmeticOpKind.Addition, arithOp.arithmetic.type);
            Assert.AreEqual(2, arithOp.arithmetic.pointers.Length);
        }

        [Test]
        public void SynthFixture_NSGetterIR_PreservesForceUnwrapCoalesceKeyOfChain()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            var score = export.attributes["attr-score"];

            // Second instruction's pointer chain:
            // forceUnwrap(coalesce(keyOf, "Unknown"))
            var secondVar = ((VariableInstruction)score.getter.instructions[1]).variable;
            var force = (ForceUnwrapPointer)secondVar.pointer;
            var coalesce = (CoalescePointer)force.pointer;
            var keyOfPtr = (KeyOfPointer)coalesce.left;
            Assert.IsTrue(keyOfPtr.optional);
            // keyOf wraps a KeyOf body — `pointer.key` is the key
            // expression.
            Assert.IsNotNull(keyOfPtr.keyOf.pointer);
            Assert.IsNotNull(keyOfPtr.keyOf.key);
        }

        [Test]
        public void SynthFixture_NSGetterIR_PreservesFunctionAndListLiteralChain()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            var score = export.attributes["attr-score"];

            // Inside the if branch:
            //   return [1, 2, 3].Where((n) => n != 0).Count();
            var ifInstr = (IfInstruction)score.getter.instructions[2];
            var ret = (ReturnInstruction)ifInstr.branches[0].instructions[0];
            var fnPtr = (FunctionPointer)ret.pointer;
            var countFn = (CountFunction)fnPtr.function;

            // Count's collectionPointer wraps the Where call.
            var whereFnPtr = (FunctionPointer)countFn.info.collectionPointer;
            var whereFn = (WhereFunction)whereFnPtr.function;

            // Where's collectionPointer wraps the list literal.
            var listLit = (ListLiteralPointer)whereFn.info.collectionPointer;
            Assert.IsNotNull(listLit.typeInfo);
            Assert.AreEqual(3, listLit.entries.Length);

            // The lambda body asserts boolean operation.
            var lambdaReturn = (ReturnInstruction)whereFn.info.function.instructions[0];
            var boolOpPtr = (OperationPointer)lambdaReturn.pointer;
            Assert.IsInstanceOf<BooleanOperation>(boolOpPtr.operation);
        }

        [Test]
        public void SynthFixture_NSGetterIR_PreservesStringifyAndDictLiteral()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            var manifest = export.attributes["attr-manifest"];
            var ret = (ReturnInstruction)manifest.getter.instructions[0];
            var stringify = (StringifyPointer)ret.pointer;
            var dictLit = (DictLiteralPointer)stringify.pointer;
            Assert.IsNotNull(dictLit.typeInfo);
            Assert.AreEqual(1, dictLit.entries.Length);
            Assert.IsNotNull(stringify.sourceType);
        }

        [Test]
        public void SynthFixture_NSGetterIR_PreservesCallGetterAndToBool()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            var active = export.attributes["attr-active"];
            var ret = (ReturnInstruction)active.getter.instructions[0];
            var toBool = (ToBoolPointer)ret.pointer;
            var callGetter = (CallGetterPointer)toBool.pointer;
            Assert.AreEqual("attr-score", callGetter.attributeId);
            Assert.IsFalse(callGetter.optional);
            Assert.IsInstanceOf<VariablePointer>(callGetter.thisPointer);
        }

        [Test]
        public void SynthFixture_AttributeValues_CoverAllValueShapes()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            var values = export.values;

            Assert.AreEqual(42, values["v-num"].value.ToObject<int>());
            Assert.AreEqual("hello", values["v-str"].value.ToObject<string>());
            Assert.IsTrue(values["v-flag"].value.ToObject<bool>());
            Assert.AreEqual(3.14f, values["v-float"].value.ToObject<float>(), 0.0001f);

            var listVal = values["v-list"].value.ToObject<string[]>();
            CollectionAssert.AreEqual(new[] { "wood", "stone" }, listVal);

            var dictVal = values["v-dict"].value
                .ToObject<System.Collections.Generic.Dictionary<string, string>>();
            Assert.AreEqual("v-name", dictVal["Name"]);
            Assert.AreEqual("type-hero", values["v-dict"].typeId);

            // Null values come through as a null-typed JToken or null
            // reference — Newtonsoft preserves the distinction.
            var nullToken = values["v-null"].value;
            Assert.IsTrue(nullToken == null
                || nullToken.Type == Newtonsoft.Json.Linq.JTokenType.Null);
        }

        [Test]
        public void SynthFixture_CustomTypeSchema_DeserializesAsDictionary()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            var hero = export.types["type-hero"];
            Assert.AreEqual("Hero", hero.name);
            Assert.AreEqual("attr-name", hero.schema["Name"]);
            Assert.AreEqual("attr-health", hero.schema["Health"]);
        }

        [Test]
        public void SynthFixture_EnumOptions_DeserializeAsDictionary()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            var element = export.enums["enum-element"];
            Assert.AreEqual("Element", element.name);
            Assert.AreEqual("Fire", element.options["fire"].text);
            Assert.AreEqual("Ice", element.options["ice"].text);
        }

        // --------------------------------------------------------------
        // Real-world fixture — captured from a live authoring session.
        // --------------------------------------------------------------

        [Test]
        public void RealWorldFixture_DeserializesIntoProjectExport()
        {
            var export = Deserialize(LoadFixture("project-example.json"));
            Assert.IsNotNull(export);
            Assert.AreEqual("Test", export.project.name);
            Assert.Greater(export.attributes.Count, 0);
            Assert.Greater(export.values.Count, 0);
            Assert.Greater(export.types.Count, 0);
        }

        [Test]
        public void RealWorldFixture_NSGetterAttributes_HaveCompiledGetters()
        {
            var export = Deserialize(LoadFixture("project-example.json"));
            int nsGetterCount = 0;
            foreach (var pair in export.attributes)
            {
                if (pair.Value.type != AttributeType.NSGetter) continue;
                nsGetterCount++;
                Assert.IsNotNull(
                    pair.Value.getter,
                    $"NSGetter {pair.Value.id} ({pair.Value.name}) lost its compiled getter");
                Assert.IsNotEmpty(
                    pair.Value.getter.instructions,
                    $"NSGetter {pair.Value.id} ({pair.Value.name}) has no instructions");
                Assert.IsNotNull(
                    pair.Value.getter.typeInfo,
                    $"NSGetter {pair.Value.id} ({pair.Value.name}) lost its typeInfo");
            }
            Assert.Greater(nsGetterCount, 0,
                "Real-world fixture should contain at least one NSGetter");
        }

        [Test]
        public void RealWorldFixture_RoundTripsThroughJsonConvert()
        {
            // Round-trip: deserialize → re-serialize → deserialize again.
            // Verifies Newtonsoft can round-trip our shape without
            // structural drift. (The default-serialize output won't be
            // byte-identical because field ordering / null elision
            // differ, but the rehydrated object graph stays equivalent.)
            var original = LoadFixture("project-example.json");
            var first = Deserialize(original);
            var reserialized = JsonConvert.SerializeObject(first);
            var second = Deserialize(reserialized);

            Assert.AreEqual(first.project.id, second.project.id);
            Assert.AreEqual(first.project.name, second.project.name);
            Assert.AreEqual(first.attributes.Count, second.attributes.Count);
            Assert.AreEqual(first.values.Count, second.values.Count);
            Assert.AreEqual(first.types.Count, second.types.Count);
            Assert.AreEqual(first.enums.Count, second.enums.Count);
        }
    }
}
